f;?></div><details class="comm-details"><summary>Ver eventos, actividad y procedencia</summary><div class="comm-details-grid"><span>Eventos: <strong><?php echo e($contactEvents?implode(', ',$contactEvents):'Sin evento asociado');?></strong></span><span>Última entrada: <strong><?php echo e($contactRow['ultima_entrada']!==''?$contactRow['ultima_entrada']:'—');?></strong></span><span>Último email: <strong><?php echo e($contactRow['ultimo_envio']!==''?$contactRow['ultimo_envio']:'—');?></strong></span><span>Fuentes: <strong><?php echo e($sources?implode(', ',$sources):'—');?></strong></span><span>Lotes: <strong><?php echo e($batches?implode(', ',$batches):'—');?></strong></span><span>Archivo: <strong><?php echo e(!empty($contactRow['import_file'])?$contactRow['import_file']:'—');?></strong></span></div></details></article>
